import random

def get_girth(adj):
    n = len(adj)
    min_girth = float('inf')
    for i in range(n):
        dist = [-1] * n
        dist[i] = 0
        queue = [i]
        while queue:
            u = queue.pop(0)
            for v in adj[u]:
                if dist[v] == -1:
                    dist[v] = dist[u] + 1
                    queue.append(v)
                elif dist[v] >= dist[u]:
                    min_girth = min(min_girth, dist[u] + dist[v] + 1)
    return min_girth

def is_3_colorable_adj(adj):
    n = len(adj)
    colors = [-1] * n
    def solve(u):
        if u == n:
            return True
        # Try colors 0, 1, 2
        for c in range(3):
            if all(colors[v] != c for v in adj[u] if v < u):
                colors[u] = c
                if solve(u + 1):
                    return True
                colors[u] = -1
        return False
    return solve(0)

def generate_graph():
    n = 24
    while True:
        # Generate a random 3-regular graph
        # Using the configuration model
        nodes = []
        for i in range(n):
            nodes.extend([i]*3)
        random.shuffle(nodes)

        adj = [set() for _ in range(n)]
        possible = True
        for i in range(0, len(nodes), 2):
            u, v = nodes[i], nodes[i+1]
            if u == v or v in adj[u]:
                possible = False
                break
            adj[u].add(v)
            adj[v].add(u)

        if not possible:
            continue

        # Check girth
        if get_girth(adj) >= 7:
            # Check 3-colorability
            if is_3_colorable_adj(adj):
                return adj

adj = generate_graph()
